import os
from weasyprint import HTML

html_content = """
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Internal Case Intake Report - Hajra Begum & Zohra</title>
    <style>
        * {
            box-sizing: border-box;
        }
        @page {
            size: A4;
            margin: 20mm 15mm;
            @bottom-right {
                content: "Page " counter(page) " of " counter(pages);
                font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
                font-size: 8pt;
                color: #64748b;
            }
            @bottom-left {
                content: "CONFIDENTIAL - INTERNAL CARE MANAGEMENT RECORD";
                font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
                font-size: 8pt;
                color: #94a3b8;
                font-weight: 600;
            }
        }
        body {
            font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
            margin: 0;
            padding: 0;
            color: #334155;
            background-color: #ffffff;
            line-height: 1.5;
            font-size: 10pt;
        }

        /* Minimalist Header Area */
        .header-container {
            border-bottom: 2px solid #334155;
            padding-bottom: 10px;
            margin-bottom: 20px;
        }
        .confidential-badge {
            font-size: 8pt;
            font-weight: bold;
            color: #475569;
            text-transform: uppercase;
            letter-spacing: 1px;
            margin-bottom: 6px;
        }
        h1 {
            color: #0f172a;
            font-size: 18pt;
            margin: 0 0 4px 0;
            letter-spacing: -0.3px;
        }
        .subtitle {
            color: #64748b;
            font-size: 10pt;
            margin: 0;
        }

        /* Simple Metadata Table */
        .meta-table {
            width: 100%;
            border-collapse: collapse;
            margin-bottom: 20px;
            border: 1px solid #cbd5e1;
        }
        .meta-table td {
            padding: 8px 10px;
            border: 1px solid #e2e8f0;
            vertical-align: top;
            font-size: 9.5pt;
        }
        .meta-label {
            font-weight: bold;
            color: #1e293b;
            width: 18%;
            background-color: #f8fafc;
        }
        .meta-value {
            color: #334155;
            width: 32%;
        }

        /* Section Headings */
        h2 {
            color: #1e293b;
            font-size: 11.5pt;
            margin: 20px 0 10px 0;
            padding-bottom: 4px;
            border-bottom: 1px solid #94a3b8;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            page-break-after: avoid;
        }

        p {
            margin: 0 0 10px 0;
            text-align: justify;
        }
        ul {
            margin: 0 0 12px 0;
            padding-left: 18px;
        }
        li {
            margin-bottom: 5px;
        }

        /* Simple Monochrome Callout Box */
        .callout-box {
            background-color: #f8fafc;
            border: 1px solid #cbd5e1;
            border-left: 4px solid #475569;
            padding: 10px 12px;
            margin: 14px 0;
            page-break-inside: avoid;
        }
        .callout-title {
            font-weight: bold;
            color: #0f172a;
            margin-bottom: 4px;
            font-size: 9.5pt;
            text-transform: uppercase;
        }
        .callout-desc {
            color: #334155;
            margin: 0;
            font-size: 9.5pt;
        }

        /* Simple Profile Table */
        .profile-table {
            width: 100%;
            border-collapse: collapse;
            margin-top: 8px;
            margin-bottom: 16px;
        }
        .profile-table th {
            background-color: #f1f5f9;
            color: #0f172a;
            text-align: left;
            padding: 8px 10px;
            font-size: 9.5pt;
            font-weight: bold;
            border: 1px solid #cbd5e1;
        }
        .profile-table td {
            padding: 10px;
            border: 1px solid #cbd5e1;
            vertical-align: top;
        }

        .bullet-title {
            font-weight: bold;
            color: #0f172a;
        }
    </style>
</head>
<body>

    <!-- Header Banner -->
    <div class="header-container">
        <div class="confidential-badge">Confidential &amp; Corporate Record</div>
        <h1>INTERNAL CARE INTAKE &amp; CONSULTATION NOTES</h1>
        <div class="subtitle">Case Management Division — Initial Assessment Log</div>
    </div>

    <!-- Intake Metadata -->
    <table class="meta-table">
        <tr>
            <td class="meta-label">Primary Contact</td>
            <td class="meta-value">Zohra (Daughter - Only Child)</td>
            <td class="meta-label">Lead Source</td>
            <td class="meta-value">Social Media (Junaid Akram’s Reel)</td>
        </tr>
        <tr>
            <td class="meta-label">Contact Location</td>
            <td class="meta-value">Buffalo, New York, USA</td>
            <td class="meta-label">Intake Date</td>
            <td class="meta-value">July 27, 2026</td>
        </tr>
        <tr>
            <td class="meta-label">Beneficiary</td>
            <td class="meta-value">Hajra Begum (Mother, Age 60+)</td>
            <td class="meta-label">Status</td>
            <td class="meta-value">Pending Family Consultation</td>
        </tr>
        <tr>
            <td class="meta-label">Service Location</td>
            <td class="meta-value" colspan="3">
                23 M, Block 2, PECHS, Karachi, Pakistan<br>
                <em>Landmark: Near Allahwali Biryani / Model School</em>
            </td>
        </tr>
    </table>

    <!-- Intake Summary & Client Disposition -->
    <h2>1. Intake Summary &amp; Client Disposition</h2>
    <p>
        The primary sponsor, Zohra, reached out from Buffalo, NY, after viewing a reel by Junaid Akram. She is an only child; her father passed away when she was three years old. He was a supervisor at Saudi Airlines, retired 10 years ago.
    </p>
    <p>
        During the initial call, Zohra expressed hesitation and trust issues regarding Field Service Officers (FSOs) visiting her mother’s residence. However, through detailed explanation of our protocols, she grew satisfied and reassured. She is very interested in moving forward but requested time to discuss the service setup with her mother before confirming onboarding.
    </p>

    <!-- Beneficiary Health Profile -->
    <h2>2. Beneficiary Health &amp; Mobility Profile</h2>
    <table class="profile-table">
        <tr>
            <th>Beneficiary Details: Hajra Begum (Age: 60+)</th>
        </tr>
        <tr>
            <td>
                <p><strong>Medical Conditions:</strong> Diagnosed with Hypertension, Arthritis, and Osteoporosis.</p>
                <p><strong>Mobility &amp; Fall History:</strong> Arthritis has severely restricted her physical mobility. The patient has a history of two significant falls, one resulting in a broken wrist bone.</p>
                <p><strong>Support Network:</strong> Local relatives are considered unreliable. Minimal informal oversight is currently provided by a few local friends of her daughter who visit periodically.</p>
            </td>
        </tr>
    </table>

    <!-- Domestic Boundaries & Privacy Directives -->
    <h2>3. Household Structure &amp; Access Constraints</h2>
    <p>
        The residence presents unique operational and privacy requirements that must be strictly observed:
    </p>
    <ul>
        <li><strong>Building Layout:</strong> The ground floor of the property is leased out to a commercial bank, while Hajra Begum resides exclusively on the 1st floor.</li>
        <li><strong>Strict Domestic Privacy Limit:</strong> The patient leads a very private life and strictly prohibits outside staff or strangers from entering her home quarters.</li>
        <li><strong>On-Site Consultation Protocol:</strong> If operational or management staff need to meet or discuss care plans in person, meetings must take place downstairs in the bank area on the ground floor. No home entry is permitted.</li>
    </ul>

    <div class="callout-box">
        <div class="callout-title">Operational Boundary Directive: Outdoor Services Only</div>
        <p class="callout-desc">
            Care deliverables for this case are strictly limited to **outdoor errands and off-site support** (e.g., procurement, bill payments, outside logistics, and prescription retrieval). Staff must not request or attempt entry into the 1st-floor living area.
        </p>
    </div>

    <!-- Mandatory Scope of Services -->
    <h2>4. Proposed Scope of Care</h2>
    <ul>
        <li>
            <span class="bullet-title">Outdoor Errand &amp; Logistic Facilitation:</span> 
            Handle groceries, utility bill payments, pharmacy pickups, and general external tasks to prevent the mother from taking unnecessary physical risks.
        </li>
        <li>
            <span class="bullet-title">Remote Health Monitoring:</span> 
            Provide off-site coordination for medical appointments, medication reminders, and health check-ins via scheduled communication channels.
        </li>
    </ul>

    <!-- Next Steps -->
    <h2>5. Operational Next Steps</h2>
    <ul>
        <li><strong>Client Follow-up:</strong> Await update from Zohra following her discussion with her mother.</li>
        <li><strong>Custom Proposal Alignment:</strong> Draft an errand-focused care package that respects domestic entry boundaries.</li>
        <li><strong>Field Team Briefing:</strong> Brief the local Karachi team regarding the ground-floor bank meeting protocol for any initial coordination.</li>
    </ul>

</body>
</html>
"""

# Save HTML file
html_filename = "Internal_Consultation_Notes_Hajra_Begum.html"
with open(html_filename, "w", encoding="utf-8") as f:
    f.write(html_content)

# Compile to PDF using WeasyPrint
pdf_filename = "Internal_Consultation_Notes_Hajra_Begum.pdf"
HTML(html_filename).write_pdf(pdf_filename)
print(f"PDF generated successfully: {pdf_filename}")

